import React, { useState } from "react";
import { Form, FormGroup, Label, Input, Row, Col } from "reactstrap";
import "../Styles/UserRegister.css";
import { Link, useNavigate } from "react-router-dom";

const MAJORS = [
  "Information Technology",
  "Business Administration",
  "Engineering",
  "Mass Communication",
];

const StudentRegister = () => {
  const navigate = useNavigate();
  const [role, setRole] = useState("student");

  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [major, setMajor] = useState(MAJORS[0]);
  const [age, setAge] = useState(20);
  const [password, setPassword] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    const payload = { fullName, email, major, age, password };
    console.log("Student Registered:", payload);
    alert("Student Registered ✅ (mock)");
  };

  // إذا اختار Company → روح لصفحة الشركة
  const handleRoleSwitch = (newRole) => {
    setRole(newRole);
    if (newRole === "company") {
      navigate("/company-register");
    }
  };

  return (
    <div className="reg-page">
      <h1 className="reg-title">
        Create your <span className="accent">account</span>
      </h1>

      {/* Role Switch */}
      <div className="role-switch">
        <button
          className={role === "student" ? "role-btn active" : "role-btn"}
          onClick={() => handleRoleSwitch("student")}
        >
          Student
        </button>

        <button
          className={role === "company" ? "role-btn active" : "role-btn"}
          onClick={() => handleRoleSwitch("company")}
        >
          Company
        </button>
      </div>

      <div className="reg-card">
        <p className="reg-sub">Please fill in your details to continue</p>

        <Form onSubmit={handleSubmit}>
          <FormGroup>
            <Label>Full Name</Label>
            <Input
              type="text"
              placeholder="Your name"
              value={fullName}
              onChange={(e) => setFullName(e.target.value)}
              required
            />
          </FormGroup>

          <FormGroup>
            <Label>Email</Label>
            <Input
              type="email"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </FormGroup>

          <FormGroup>
            <Label>Password</Label>
            <Input
              type="password"
              placeholder="********"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </FormGroup>

          <Row>
            <Col md={6}>
              <FormGroup>
                <Label>Major</Label>
                <Input
                  type="select"
                  value={major}
                  onChange={(e) => setMajor(e.target.value)}
                >
                  {MAJORS.map((m) => (
                    <option key={m}>{m}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>

            <Col md={6}>
              <FormGroup>
                <Label>Age</Label>
                <Input
                  type="number"
                  min="17"
                  max="45"
                  value={age}
                  onChange={(e) => setAge(e.target.value)}
                />
              </FormGroup>
            </Col>
          </Row>

          <button className="reg-btn">Sign up</button>

          <p className="login-text">
            Already have an account?{" "}
            <Link to="/login" className="login-link">
              Log in now!
            </Link>
          </p>
        </Form>
      </div>
    </div>
  );
};

export default StudentRegister;
